import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s_in = scanner.nextLine();
        StringBuilder s_out = new StringBuilder();
        boolean at_state = false;
        s_in += "###";

        for (int i = 0; i < s_in.length() - 3; i++) {
            if (s_out.length() == 0) {
                s_out.append(s_in.charAt(i));
                continue;
            }
            if (s_in.charAt(i) == 'd' && s_in.charAt(i + 1) == 'o' && s_in.charAt(i + 2) == 't') {
                s_out.append('.');
                i += 2;
            } else if (s_in.charAt(i) == 'a' && s_in.charAt(i + 1) == 't' && !at_state) {
                at_state = true;
                s_out.append('@');
                i += 1;
            } else {
                s_out.append(s_in.charAt(i));
            }
        }
        if (s_out.length() > 0 && s_out.charAt(s_out.length() - 1) == '.') {
            s_out.setCharAt(s_out.length() - 1, 'd');
            s_out.append("ot");
        }
        System.out.println(s_out.toString());
        scanner.close();
    }
}
